(7315951, 1141641, 77196, '<td valign="top">Haven''t seen one of those in a while. Nice collection. nice arrangement.</td>', 'Haven''t seen one of those in a while. Nice collection. nice arrangement.', '2015-02-11 04:57:22.000000', NULL, 1),
(7315952, 1141487, 77196, '<td valign="top">Put some clothes on, Woody! Great picture. Made me smile.</td>', 'Put some clothes on, Woody! Great picture. Made me smile.', '2015-02-11 05:06:51.000000', NULL, 1),
(7315953, 1141398, 77196, '<td valign="top">Absolutely love this. The muted colors, the grass blowing in the wind. The arrangement of the boat, nets, and tee pee poles(?).</td>', 'Absolutely love this. The muted colors, the grass blowing in the wind. The arrangement of the boat, nets, and tee pee poles(?).', '2015-02-11 05:10:01.000000', NULL, 1),
(7315954, 1141469, 77196, '<td valign="top">Nice use of shallow dof. I like the shells. I find the edge of the counter, and lines of its intersection with the wall and corner very distracting. To me the image has multiple focuses and can''t make up its mind what it is showing the viewer.</td>', 'Nice use of shallow dof. I like the shells. I find the edge of the counter, and lines of its intersection with the wall and corner very distracting. To me the image has multiple focuses and can''t make up its mind what it is showing the viewer.', '2015-02-11 05:15:39.000000', NULL, 1),
(7315955, 1141649, 77196, '<td valign="top">Love old clocks, and this is very nicely done. Love the reflected numbers in the glass, and the shadow of the key. Wish I cou see more of the clock, but having it hidden in shadow works in this image.</td>', 'Love old clocks, and this is very nicely done. Love the reflected numbers in the glass, and the shadow of the key. Wish I cou see more of the clock, but having it hidden in shadow works in this image.', '2015-02-11 05:19:08.000000', NULL, 1),
(7315956, 1141623, 77196, '<td valign="top">Good eye. The white accent boards and roof angles really make this shot. Nice lighting too.</td>', 'Good eye. The white accent boards and roof angles really make this shot. Nice lighting too.', '2015-02-11 05:21:00.000000', NULL, 1),
(7315958, 1141612, 77196, '<td valign="top">What awful animal abuse! (At least to some)<br/>Did you hear about the high school pranksters that painted the numbers 1, 2, and 4 on three sheep and turned them loose in the high school? Yep, the staff spent most of the day looking for #3. <br/>Great image.</td>', 'What awful animal abuse! (At least to some)Did you hear about the high school pranksters that painted the numbers 1, 2, and 4 on three sheep and turned them loose in the high school? Yep, the staff spent most of the day looking for #3. Great image.', '2015-02-11 05:29:44.000000', NULL, 1),
